import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BN3Eol-0.js";const p=JSON.parse('{"title":"UX records (UXR)","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/records/README.md","filePath":"uxs/records/README.md"}'),n={name:"uxs/records/README.md"};function s(i,e,d,c,h,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="ux-records-uxr" tabindex="-1">UX records (UXR) <a class="header-anchor" href="#ux-records-uxr" aria-label="Permalink to &quot;UX records (UXR)&quot;">​</a></h1><p>Dated records of what happened in the UX work: an operator feedback list, a review run, its findings, a plan of action, a decision session. Each is written once; a later event gets a new record. Where they sit among the UX documents: <a href="./../UXS-000-orrery-ux-architecture">UXS-000</a>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>One event, one record</strong>, numbered in order and dated in the filename: <code>UXR-NNN-YYYY-MM-DD-&lt;slug&gt;.md</code>.</li><li><strong>A record is not rewritten.</strong> If the operator changes a point later, the change is a new record or a UXD; the original stays as the input it was.</li><li><strong>A record does not decide.</strong> Decisions are <a href="./../decisions/README">UXDs</a>. A record lists what was said, by whom, and which points it contains; the UXDs and the <a href="./../CHANGE-INVENTORY">change inventory</a> say what happens to them.</li><li><strong>Large lists are referenced, not copied.</strong> The full numbered list stays in its working document (named by path in the record); the record summarises by area with the point ids.</li><li><strong>No private or operational content.</strong> Only the UX content and who said it.</li></ul><h2 id="index" tabindex="-1">Index <a class="header-anchor" href="#index" aria-label="Permalink to &quot;Index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UXR</th><th>Date</th><th>Record</th></tr></thead><tbody><tr><td><a href="./UXR-001-2026-11-11-operator-feedback">UXR-001</a></td><td>2026-11-11</td><td>The operator&#39;s feedback list on the live UI: 120 numbered points, answers and clarifications</td></tr></tbody></table>',6)])])}const f=t(n,[["render",s]]);export{p as __pageData,f as default};
